hooks.command:
if [ -f "${PLUGIN_ROOT}/scripts/loom_checker.py" ]; then exec python3 "${PLUGIN_ROOT}/scripts/loom_checker.py" push --hook; else exec python3 -c 'import json, os, re, shlex, shutil, sys
checker = os.path.join(os.environ.get("PLUGIN_ROOT", ""), "scripts", "loom_checker.py")
def deny():
 print(f"BLOCK push.attestation: installed checker is unavailable at {checker}; restart Codex to load the installed plugin version", file=sys.stderr)
 raise SystemExit(2)
try:
 payload = json.load(sys.stdin)
 if not isinstance(payload, dict) or payload.get("tool_name") != "Bash": deny()
 command = payload.get("tool_input", {}).get("command")
 if not isinstance(command, str) or not command.strip(): deny()
 tokens = shlex.split(command)
except (ValueError, TypeError, AttributeError):
 deny()
if not tokens or any(ch in command for ch in "\n;&|<>$`()") or "/" in tokens[0]: deny()
name = tokens[0]
trusted = {"git": {"/usr/bin/git"}, "ls": {"/bin/ls", "/usr/bin/ls"}, "cat": {"/bin/cat", "/usr/bin/cat"}, "find": {"/usr/bin/find", "/bin/find"}, "rg": {"/opt/homebrew/bin/rg", "/usr/local/bin/rg", "/usr/bin/rg"}}
resolved = shutil.which(name)
if name not in trusted or not resolved or os.path.abspath(resolved) not in trusted[name]: deny()
def options_ok(args, exact, prefixes=()):
 return all(not token.startswith("-") or token == "--" or token in exact or any(token.startswith(p) for p in prefixes) for token in args)
allowed = False
if name == "git":
 index = 1
 if len(tokens) > 2 and tokens[1] == "-C" and not tokens[2].startswith("-"): index = 3
 if len(tokens) <= index: deny()
 sub, args = tokens[index], tokens[index + 1:]
 common = {"--stat", "--shortstat", "--name-only", "--name-status", "--oneline", "--no-patch", "--patch", "-p", "--decorate", "--no-decorate", "--all", "--first-parent", "--reverse", "--check", "--cached", "--staged", "--quiet", "--exit-code", "--"}
 prefixes = ("--max-count=", "--format=", "--pretty=", "--since=", "--until=", "--author=", "--grep=", "--date=", "--diff-filter=")
 if sub == "status": allowed = options_ok(args, {"-s", "--short", "-b", "--branch", "--porcelain", "--show-stash", "--ahead-behind", "--no-ahead-behind", "-z", "--ignored", "--no-renames", "--"}, ("--porcelain=", "--untracked-files=", "--ignored=", "--find-renames="))
 elif sub in {"log", "show", "diff"}: allowed = options_ok(args, common, prefixes) and all(not re.fullmatch(r"-[0-9]+", a) or int(a[1:]) >= 0 for a in args)
 elif sub == "branch": allowed = options_ok(args, {"--list", "--"}) and all(not a.startswith("-") or a in {"--list", "--"} for a in args)
elif name == "cat":
 allowed = options_ok(tokens[1:], {"--"}) and all(not a.startswith("-") or re.fullmatch(r"-[benstuv]+", a) for a in tokens[1:])
elif name == "ls":
 allowed = options_ok(tokens[1:], {"--"}) and all(not a.startswith("-") or re.fullmatch(r"-[AabdFfGghiklmnopqrstuwx1@%]+", a) for a in tokens[1:])
elif name == "rg":
 allowed = options_ok(tokens[1:], {"-n", "--line-number", "-l", "--files-with-matches", "--files", "--hidden", "-S", "--smart-case", "-i", "--ignore-case", "-F", "--fixed-strings", "--no-heading", "--"}, ("--glob=", "--type=", "--color="))
elif name == "find":
 values = {"-maxdepth", "-mindepth", "-type", "-name", "-iname", "-path", "-ipath"}
 flags = {"-print", "-xdev", "-depth", "-L", "-H", "-P", "!", "(", ")"}
 i, allowed = 1, True
 while i < len(tokens):
  token = tokens[i]
  if token in values:
   i += 1
   if i >= len(tokens): allowed = False; break
  elif token.startswith("-") and token not in flags:
   allowed = False; break
  i += 1
if not allowed: deny()' ; fi
